export interface ConnectorConfig {
  /** Slack bot token with chat:write scope */
  slackBotToken: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioWebhookPayload {
  Body: string
  From: string
  MessagingServiceSid?: string
}

export interface SlackMessageResult {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  slackMessageId: string
  channel: string
}

const SALES_KEYWORDS = /pricing|quote|demo/i

function determineChannel(body: string): string {
  return SALES_KEYWORDS.test(body) ? '#sales' : '#support'
}

export async function handle(
  payload: TwilioWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }

  const channel = determineChannel(payload.Body)
  const text = payload.Body

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel, text })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = await response.json() as SlackMessageResult
  return {
    slackMessageId: result.ts,
    channel: result.channel
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TwilioWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('#sales')
    expect(result.slackMessageId).toBe('1234567890.123456')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let mockFetch: typeof fetch
  let calls: ReturnType<typeof fakeFetch>['calls']

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: req.json?.channel, ts: '1234567890.123456' })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    mockFetch = fetch
    calls = recordedCalls
    baseConfig = {
      slackBotToken: 'xoxb-test-token',
      fetch: mockFetch
    }
  })

  it('routes to #sales when body contains pricing keyword', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'I need pricing information',
      From: '+15551234567'
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I need pricing information' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
  })

  it('routes to #sales when body contains quote keyword', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Please send me a quote',
      From: '+15551234567'
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Please send me a quote' })
  })

  it('routes to #sales when body contains demo keyword', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Can I schedule a demo?',
      From: '+15551234567'
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Can I schedule a demo?' })
  })

  it('routes to #support when body does not match sales keywords', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Hello, I have a general question',
      From: '+15551234567'
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#support')
    expect(calls[0].json).toEqual({ channel: '#support', text: 'Hello, I have a general question' })
  })

  it('uses case-insensitive matching for sales keywords', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'PRICING please',
      From: '+15551234567'
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('#sales')
  })

  it('includes From field in payload but does not send to Slack', async () => {
    const payload: TwilioWebhookPayload = {
      Body: 'Quote request',
      From: '+15559876543',
      MessagingServiceSid: 'MGXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'
    }
    await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Quote request' })
  })

  it('throws descriptive error when Body is missing', async () => {
    const payload = { From: '+15551234567' } as unknown as TwilioWebhookPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: Body')
  })

  it('throws descriptive error when From is missing', async () => {
    const payload = { Body: 'Hello' } as unknown as TwilioWebhookPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: From')
  })

  it('throws descriptive error when Body is empty string', async () => {
    const payload: TwilioWebhookPayload = { Body: '', From: '+15551234567' }
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: Body')
  })

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const config: ConnectorConfig = { slackBotToken: 'bad-token', fetch }
    const payload: TwilioWebhookPayload = { Body: 'Quote please', From: '+15551234567' }
    await expect(handle(payload, config)).rejects.toThrow('Slack API error: 401 Unauthorized for POST https://slack.com/api/chat.postMessage')
    expect(errorCalls.length).toBe(1)
  })

  it('throws error on 500 response', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'server_error' }, 500))
    const config: ConnectorConfig = { slackBotToken: 'xoxb-test-token', fetch }
    const payload: TwilioWebhookPayload = { Body: 'Quote please', From: '+15551234567' }
    await expect(handle(payload, config)).rejects.toThrow('Slack API error: 500 Internal Server Error for POST https://slack.com/api/chat.postMessage')
    expect(errorCalls.length).toBe(1)
  })

  it('sends correct Authorization header with Bearer token', async () => {
    const payload: TwilioWebhookPayload = { Body: 'Demo request', From: '+15551234567' }
    await handle(payload, baseConfig)
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
  })

  it('sends Content-Type application/json', async () => {
    const payload: TwilioWebhookPayload = { Body: 'Demo request', From: '+15551234567' }
    await handle(payload, baseConfig)
    expect(calls[0].headers.get('content-type')).toBe('application/json')
  })

  it('returns slack message ts as slackMessageId', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true, channel: '#sales', ts: '9876543210.987654' }))
    const config: ConnectorConfig = { slackBotToken: 'xoxb-test-token', fetch }
    const payload: TwilioWebhookPayload = { Body: 'Quote', From: '+15551234567' }
    const result = await handle(payload, config)
    expect(result.slackMessageId).toBe('9876543210.987654')
  })
})

